import "server-only";

import type { UsagePeriodKind } from "@/generated/prisma/client";
import {
  getEffectivePlan,
  hasUnresolvedBillingPeriod,
  type EntitlementUser,
} from "@/lib/entitlements";
import { AppError } from "@/lib/errors";
import { resolveSubscriptionLifecycle } from "@/lib/subscription-lifecycle";
import { PLANS } from "@/lib/plans";

export type UsagePeriodSpec = {
  key: string;
  kind: UsagePeriodKind;
  startsAt: Date;
  endsAt: Date;
  operationalEndsAt: Date;
  limit: number;
};
export type UsagePeriods = { daily: UsagePeriodSpec; monthly: UsagePeriodSpec };

export class UsagePeriodError extends AppError {
  readonly code = "BILLING_PERIOD_UNRESOLVED";
  constructor() {
    super("Sending is paused until the subscription period is verified.");
  }
}

/** Half-open UTC periods. Grace extends one allowance, never its identity. */
export function resolveUsagePeriods(
  user: EntitlementUser,
  now = new Date(Date.now()),
): UsagePeriods {
  if (!Number.isFinite(now.getTime())) throw new Error("Invalid usage time.");
  const plan = getEffectivePlan(user, now);
  const limits = PLANS[plan];
  const start = new Date(
    Date.UTC(now.getUTCFullYear(), now.getUTCMonth(), now.getUTCDate()),
  );
  const end = new Date(start.getTime() + 86400000);
  const daily: UsagePeriodSpec = {
    key: `day:${start.toISOString()}`,
    kind: "DAILY",
    startsAt: start,
    endsAt: end,
    operationalEndsAt: end,
    limit: limits.dailyEmails,
  };
  const providerStart = user.currentPeriodStart;
  const providerEnd = user.currentPeriodEnd;
  const validProvider = resolveSubscriptionLifecycle(user, now).paid;
  // A verified expired/cancelled subscription can downgrade; an active billing
  // boundary cannot invent a new calendar allowance, even under a paid grant.
  if (hasUnresolvedBillingPeriod(user, now)) throw new UsagePeriodError();
  if (plan === "PAID" && validProvider) {
    return {
      daily,
      monthly: {
        key: `provider:${JSON.stringify([user.dodoSubscriptionId, providerStart!.toISOString(), providerEnd!.toISOString()])}`,
        kind: "MONTHLY",
        startsAt: providerStart!,
        endsAt: providerEnd!,
        operationalEndsAt:
          user.subscriptionStatus === "PAST_DUE" &&
          user.gracePeriodEnd! > providerEnd!
            ? user.gracePeriodEnd!
            : providerEnd!,
        limit: limits.monthlyEmails,
      },
    };
  }
  const monthStart = new Date(
    Date.UTC(now.getUTCFullYear(), now.getUTCMonth(), 1),
  );
  const monthEnd = new Date(
    Date.UTC(now.getUTCFullYear(), now.getUTCMonth() + 1, 1),
  );
  return {
    daily,
    monthly: {
      key: `month:${monthStart.toISOString()}`,
      kind: "MONTHLY",
      startsAt: monthStart,
      endsAt: monthEnd,
      operationalEndsAt: monthEnd,
      limit: limits.monthlyEmails,
    },
  };
}

/** Historical attempts keep their UTC charge date. Only known exact provider
 * boundaries can be used; imported evidence seeds any later overlapping bucket. */
export function historicalUsagePeriods(
  user: EntitlementUser,
  at: Date,
): UsagePeriods {
  const calendar = resolveUsagePeriods(
    {
      ...user,
      plan: "FREE",
      subscriptionStatus: "NONE",
      planOverride: null,
      grandfatheredUntil: null,
    },
    at,
  );
  const end = user.gracePeriodEnd ?? user.currentPeriodEnd;
  if (
    user.dodoSubscriptionId &&
    user.currentPeriodStart &&
    user.currentPeriodEnd &&
    user.currentPeriodStart <= at &&
    end &&
    at < end
  ) {
    return resolveUsagePeriods(
      {
        ...user,
        plan: "PAID",
        planOverride: null,
        grandfatheredUntil: null,
        subscriptionStatus: at < user.currentPeriodEnd ? "ACTIVE" : "PAST_DUE",
      },
      at,
    );
  }
  return calendar;
}
